@media (prefers-color-scheme:dark) {
  :root:not(:where([data-theme="light"])) {
    color-scheme: dark;
    --success-100: #1C2B1F;
    --success-300: #2E4A34;
    --success-600: #5FB86E;
    --success-contrast: #1E1A14;
    --warning-100: #2E2413;
