    --danger-600: #E85D4A;
    --danger-700: #F47765;
    --danger-contrast: #1E1A14;
    --chart-1: #3987E5;
    --chart-2: #D95926;
    --chart-3: #199E70;
    --chart-4: #9085E9;
    --chart-5: #D55181;
    --surface-page: #191512;
