    --border-strong: #453C31;
    --border-inverse: rgba(30,26,20,.2);
    --border-control: var(--sand-600);
    --border-control-hover: var(--sand-400);
    --accent: #F3EFE7;
    --accent-hover: #FFFFFF;
    --accent-active: #D5CFC0;
    --accent-subtle: #2A2119;
    --accent-subtle-border: #453728;
