@media (prefers-contrast: more) {
  :root {
    --text-muted: var(--text-secondary);
    --border-default: var(--border-control);
  }
}

@media (prefers-contrast: more) {
  [data-theme="dark"] {
    --text-muted: var(--text-secondary);
    --border-default: var(--border-control);
  }
}

@media (prefers-contrast: more) and (prefers-color-scheme:dark) {
  :root:not(:where([data-theme="light"])) {
    --text-muted: var(--text-secondary);
    --border-default: var(--border-control);
  }
}

